mapper.select:
SELECT p.id, p.product_name, p.product_title, p.main_image, p.season_tag, COALESCE(MIN(s.price), 0) AS min_price, COALESCE(MAX(s.price), 0) AS max_price, COALESCE(MIN(s.original_price), NULL) AS original_price, COALESCE(SUM(s.sales), 0) AS sales, c.category_name FROM biz_product p LEFT JOIN biz_category c ON p.category_id = c.id LEFT JOIN biz_product_sku s ON p.id = s.product_id AND s.status = 1 WHERE p.status = 1
AND p.category_id = #{dto.categoryId}
AND (p.product_name LIKE CONCAT('%', #{dto.keyword}, '%') OR p.product_title LIKE CONCAT('%', #{dto.keyword}, '%'))
AND p.merchant_id = #{dto.merchantId}
GROUP BY p.id, p.product_name, p.product_title, p.main_image, c.category_name ORDER BY p.sort_order DESC, p.id DESC

SELECT spa.product_id, spa.attr_id, a.attr_name, spa.attr_value_id, av.value AS attr_value FROM biz_product_spu_attr spa LEFT JOIN biz_attribute a ON spa.attr_id = a.id LEFT JOIN biz_attribute_value av ON spa.attr_value_id = av.id WHERE spa.product_id IN
#{id}
ORDER BY spa.attr_id, av.sort_order

SELECT sku_attr.sku_id, sku_attr.attr_id, a.attr_name, sku_attr.attr_value_id, av.value AS attr_value FROM biz_product_sku_attr sku_attr LEFT JOIN biz_attribute a ON sku_attr.attr_id = a.id LEFT JOIN biz_attribute_value av ON sku_attr.attr_value_id = av.id WHERE sku_attr.sku_id IN
#{id}
ORDER BY sku_attr.sku_id, a.sort_order, av.sort_order
